int expectedWidth = sourceImage.getWidth() + 50;
int expectedHeight = sourceImage.getHeight() + 50;

net.coobird.thumbnailator.filters.Canvas canvasFilter = new net.coobird.thumbnailator.filters.Canvas(
    expectedWidth, 
    expectedHeight, 
    net.coobird.thumbnailator.geometry.Positions.CENTER, 
    false, 
    java.awt.Color.BLUE
);

java.awt.image.BufferedImage result = canvasFilter.apply(sourceImage);

assert result != null : "Resulting image should not be null";
assert result.getWidth() == expectedWidth : "Result width should match the canvas width";
assert result.getHeight() == expectedHeight : "Result height should match the canvas height";

int topLeftRGB = result.getRGB(0, 0);
assert topLeftRGB == java.awt.Color.BLUE.getRGB() : "Top-left pixel should be filled with the specified canvas color";

System.out.println("__CHECK__ Canvas " + result.getWidth() + "x" + result.getHeight() + " filled with " + topLeftRGB);

